    /** Calculates the *local* player’s 7‑day XP by averaging the two downstream API calls. */
    private double calculateXP() {
        try {
            double womXP = WOMApiClient.getPlayerGains(getLocalPlayerName());
            double templeXP = 0;
            try {
                String templeResp = TempleApiClient.getPlayerGains(getLocalPlayerName());
                templeXP = parseXPFromResponse(templeResp);
